// Diagrams deployed without a <bpmndi:BPMNDiagram> (written by hand or generated by code) import
// fine but bpmn-js draws nothing: shapes come only from DI. importXml lays such a process out with
// bpmn.io's bpmn-auto-layout before drawing it. The module is loaded on first need only.
window.fleansAutoLayout = {
    _moduleUrl: 'https://cdn.jsdelivr.net/npm/bpmn-auto-layout@1.3.0/+esm',

    /** Imports `xml` into a bpmn-js Viewer/Modeler, laying it out first when it has no diagram. */
    importXml: async function (bpmnJs, xml) {
        // importXML rejects a diagram-less file ("no diagram to display"), so check it first, parsed
        // with the instance's own moddle (it carries the fleans:/zeebe: extensions).
        var moddle = bpmnJs.get('moddle');
        var definitions = (await moddle.fromXML(xml, 'bpmn:Definitions')).rootElement;
        if (!definitions.diagrams || !definitions.diagrams.length) {
            // The layout walks incoming/outgoing, which a hand-written process often leaves out
            // (the engine only needs sourceRef/targetRef), so derive them from the flows first.
            this._linkFlows(definitions.rootElements || []);
            var layoutProcess = (await import(this._moduleUrl)).layoutProcess;
            xml = await layoutProcess((await moddle.toXML(definitions)).xml);
        }
        await bpmnJs.importXML(xml);
    },

    _linkFlows: function (elements) {
        var self = this;
        elements.forEach(function (element) {
            var children = element.flowElements || [];
            children.forEach(function (flow) {
                if (flow.$type !== 'bpmn:SequenceFlow' || !flow.sourceRef || !flow.targetRef) return;
                var outgoing = flow.sourceRef.get('outgoing');
                var incoming = flow.targetRef.get('incoming');
                if (outgoing.indexOf(flow) === -1) outgoing.push(flow);
                if (incoming.indexOf(flow) === -1) incoming.push(flow);
            });
            self._linkFlows(children.filter(function (c) { return c.flowElements; }));
        });
    }
};
